<script setup lang="ts">
import { uiText, uiLocale } from '@/i18n'

import { onMounted,ref } from 'vue'
import { researchApi } from '@/api/research'
import { request } from '@/api/client'
import { authStore } from '@/stores/auth'
const items=ref<Awaited<ReturnType<typeof researchApi.trash>>>([]),error=ref(''),busy=ref(false),page=ref(0),health=ref<{database:string;drill?:{lastSuccess?:string;lastAttempt?:string;success:boolean;message?:string;checks?:{attachmentsChecked?:number}};backup:{lastSuccess:string;bytes:number;lastError?:string;warning?:string;verified?:boolean;scheduled?:boolean;retained?:number}|null}>()
async function load(){busy.value=true;error.value='';try{items.value=await researchApi.trash(page.value)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function restore(id:string){busy.value=true;try{await researchApi.restore(id);await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function purge(id:string){if(!confirm(uiText('永久删除这篇笔记及历史版本？此操作无法撤销。')))return;busy.value=true;try{await researchApi.purge(id);await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{if(authStore.has('note:read'))await load();if(authStore.state.user?.roleCode==='ADMIN'){try{health.value=await request('/research/recovery-status')}catch(e){error.value=(e as Error).message}}})
</script>
<template><div><p v-if="error" class="inline-alert inline-alert--error" role="alert">{{ uiText(error) }}</p><div class="research-columns"><section><h2>{{ uiText('笔记回收站') }}</h2><p class="research-hint">{{ uiText('恢复后回到笔记列表顶层。旧分享链接保持撤销，避免恢复时意外扩大访问范围。') }}</p><p v-if="!items.length" class="research-empty">{{ uiText('回收站是空的。') }}</p><article v-for="i in items" :key="i.id" class="research-list-row"><div><strong>{{ i.title }}</strong><p>{{ new Date(i.deletedAt).toLocaleString(uiLocale()) }} {{ uiText('移入') }}</p></div><div class="research-actions"><button class="button button--ghost" :disabled="busy||!authStore.has('note:write')" @click="restore(i.id)">{{ uiText('恢复') }}</button><button class="button button--ghost" :disabled="busy||!authStore.has('note:write')" @click="purge(i.id)">{{ uiText('永久删除') }}</button></div></article><div class="research-pagination"><button class="button button--ghost" :disabled="!page||busy" @click="page--;load()">{{ uiText('上一页') }}</button><button class="button button--ghost" :disabled="items.length<30||busy" @click="page++;load()">{{ uiText('下一页') }}</button></div></section>
 <section class="research-card"><h2>{{ uiText('完整备份与恢复') }}</h2><p class="research-hint">{{ uiText('安装管理员在服务器终端运行备份工具。网站不持有 Docker 控制权限。') }}</p><template v-if="health"><div v-if="health.drill"><p>{{ uiText('恢复演练：') }}{{health.drill.success?uiText('通过'):uiText('待处理')}} · {{new Date(health.drill.lastSuccess||health.drill.lastAttempt||'').toLocaleString(uiLocale())}}</p><p v-if="health.drill.message" class="form-error">{{health.drill.message}}</p><p v-if="health.drill.success" class="research-hint">{{ uiText('已验证独立恢复实例的服务、登录、笔记读写；核验') }} {{health.drill.checks?.attachmentsChecked||0}} {{ uiText('份附件。') }}</p></div><p v-else class="research-hint">{{ uiText('尚无恢复演练记录。自动备份配置后默认每七天在隔离环境验证一次。') }}</p><p>{{ uiText('数据库：') }}{{ health.database==='UP'?uiText('运行正常'):uiText('待检查') }}</p><p v-if="health.backup?.lastError||health.backup?.warning" class="form-error" role="alert">{{health.backup.lastError||health.backup.warning}}</p><p v-if="health.backup?.scheduled">{{ uiText('每日自动备份 · 保留') }} {{health.backup.retained??0}} {{ uiText('份 ·') }} {{health.backup.verified?uiText('已验证'):uiText('待验证')}}</p><p>{{ uiText('最近备份：') }}{{ health.backup?.lastSuccess?new Date(health.backup.lastSuccess).toLocaleString(uiLocale()):uiText('尚无成功记录') }}</p></template><ol class="backup-steps"><li>{{ uiText('首次安装备份工具依赖') }}<code>python -m pip install -r scripts/backup/requirements.txt</code></li><li>{{ uiText('创建加密备份，按提示设置密码') }}<code>python scripts/backup/compose_backup.py backup backups/my-backup.pkb</code></li><li>{{ uiText('检查密码与全部数据的完整性') }}<code>python scripts/backup/compose_backup.py verify backups/my-backup.pkb</code></li><li>{{ uiText('恢复到独立的新数据卷') }}<code>python scripts/backup/compose_backup.py restore backups/my-backup.pkb --restore-name pkb-restore-check01</code></li></ol><p class="research-hint">{{ uiText('备份期间服务会暂时停止，快照完成后恢复原运行状态。覆盖数据库、附件、Redis、训练数据与原始配置；备份密码由你保管。备份目录可设在独立磁盘或受保护的同步目录。') }}</p><RouterLink to="/docs">{{ uiText('操作文档 →') }}</RouterLink></section></div></div></template>
<style scoped>.backup-steps{padding-left:20px;font-size:13px;line-height:1.8}.backup-steps li{padding-bottom:20px}.backup-steps code{display:block;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;margin-top:8px;padding:12px;background:var(--code-paper)}.research-card{align-self:start}</style>
